303:   /* ------------------------------------------------------------- buildings */
304:   function facadeTextures(baseColor, floors, cols, litChance) {
305:     const W = 256, H = 512;
306:     const map = makeCanvas(W, H);
307:     const glow = makeCanvas(W, H);
308:     const ctx = map.getContext('2d');
309:     const gtx = glow.getContext('2d');
310:     ctx.fillStyle = baseColor;
311:     ctx.fillRect(0, 0, W, H);
312:     gtx.fillStyle = '#000';
313:     gtx.fillRect(0, 0, W, H);
314: 
315:     // brick and grime
316:     for (let i = 0; i < 1100; i++) {
317:       ctx.fillStyle = rng() > 0.5 ? `rgba(255,255,255,${0.015 + rng() * 0.03})` : `rgba(0,0,0,${0.03 + rng() * 0.07})`;
318:       ctx.fillRect(rng() * W, rng() * H, 2 + rng() * 5, 1 + rng() * 2);
319:     }
320:     ctx.strokeStyle = 'rgba(0,0,0,.14)';
321:     ctx.lineWidth = 1;
322:     for (let y = 0; y < H; y += 12) {
323:       ctx.beginPath();
324:       ctx.moveTo(0, y);
325:       ctx.lineTo(W, y);
326:       ctx.stroke();
327:     }
328:     const top = H * 0.08;
329:     const usableH = H * 0.82;
330:     const windowW = Math.max(11, W / (cols * 3.1));
331:     const windowH = Math.max(16, usableH / (floors * 2.5));
332:     for (let floor = 0; floor < floors; floor++) {
333:       for (let col = 0; col < cols; col++) {
334:         const cx = (col + 0.5) * (W / cols);
335:         const cy = top + (floor + 0.4) * (usableH / floors);
336:         const light = rng() < litChance;
337:         ctx.fillStyle = '#38414a';
338:         ctx.fillRect(cx - windowW / 2, cy - windowH / 2, windowW, windowH);
339:         ctx.fillStyle = 'rgba(4,8,13,.62)';
340:         ctx.fillRect(cx - windowW / 2 + 3, cy - windowH / 2 + 3, windowW - 6, windowH - 6);
341:         if (light) {
342:           const warm = rng() > 0.3;
343:           const colr = warm ? (rng() > 0.75 ? '#6fe7ff' : '#ffc878') : '#e9f3ff';
344:           ctx.fillStyle = warm ? 'rgba(255,188,99,.38)' : 'rgba(174,220,255,.28)';
345:           ctx.fillRect(cx - windowW / 2 + 3, cy - windowH / 2 + 3, windowW - 6, windowH - 6);
346:           gtx.fillStyle = colr;
347:           gtx.globalAlpha = 0.35 + rng() * 0.55;
348:           gtx.fillRect(cx - windowW / 2 + 3, cy - windowH / 2 + 3, windowW - 6, windowH - 6);
349:           gtx.globalAlpha = 1;
350:         }
351:         // Window frame.
352:         ctx.strokeStyle = 'rgba(0,0,0,.5)';
353:         ctx.lineWidth = 2;
354:         ctx.strokeRect(cx - windowW / 2, cy - windowH / 2, windowW, windowH);
355:       }
356:     }
357:     // Top and bottom trim.
358:     ctx.fillStyle = 'rgba(0,0,0,.23)';
359:     ctx.fillRect(0, H - 26, W, 26);
360:     ctx.fillStyle = 'rgba(255,255,255,.06)';
361:     ctx.fillRect(0, 0, W, 8);
362:     return {
363:       map: canvasTexture(map, { anisotropy: 8 }),
364:       glow: canvasTexture(glow, { anisotropy: 8 }),
365:     };
366:   }
