368:   function addBuilding({
369:     x, z, w, d, h = 8, color = 0x4c463d, floors = 3, cols = 4,
370:     lit = 0.24, roof = 0x15181b, collider = true, trim = 0x2a2825,
371:   }) {
372:     const base = `#${new THREE.Color(color).getHexString()}`;
373:     const textures = facadeTextures(base, floors, cols, lit);
374:     const side = new THREE.MeshStandardMaterial({
375:       map: textures.map,
376:       emissiveMap: textures.glow,
377:       emissive: 0xffffff,
378:       emissiveIntensity: 0.58,
379:       roughness: 0.93,
380:       metalness: 0.02,
381:     });
382:     const roofMat = new THREE.MeshStandardMaterial({ color: roof, roughness: 0.9 });
383:     const mesh = new THREE.Mesh(
384:       new THREE.BoxGeometry(w, h, d),
385:       [side, side, roofMat, roofMat, side, side],
386:     );
387:     mesh.position.set(x, h / 2, z);
388:     scene.add(mesh);
389:     const cornice = meshBox(w + 0.9, 0.38, d + 0.9, new THREE.MeshStandardMaterial({ color: trim, roughness: 0.88 }), x, h + 0.1, z);
390:     scene.add(cornice);
391:     if (collider) addCollider(x, z, w, d);
392:     return mesh;
393:   }
