861:   /* -------------------------------------------------------------------- rifts */
862:   const portalVertex = /* glsl */`
863:     varying vec2 vUv;
864:     void main() {
865:       vUv = uv;
866:       gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
867:     }
868:   `;
869:   const portalFragment = /* glsl */`
870:     uniform float time;
871:     uniform vec3 hot;
872:     uniform vec3 cold;
873:     varying vec2 vUv;
874:     float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
875:     float noise(vec2 p) {
876:       vec2 i = floor(p); vec2 f = fract(p);
877:       vec2 u = f * f * (3.0 - 2.0 * f);
878:       return mix(mix(hash(i), hash(i + vec2(1,0)), u.x), mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), u.x), u.y);
879:     }
880:     void main() {
881:       vec2 p = vUv - 0.5;
882:       p.x *= 0.72;
883:       float r = length(p) * 2.0;
884:       float a = atan(p.y, p.x);
885:       float swirl = sin(a * 5.0 + r * 16.0 - time * 2.4 + noise(p * 8.0 + time * 0.2) * 5.0);
886:       float inner = smoothstep(1.03, 0.16, r);
887:       float rim = smoothstep(0.84, 0.67, r) * smoothstep(0.38, 0.63, r);
888:       float veins = smoothstep(0.25, 0.9, swirl * 0.5 + 0.5) * smoothstep(1.0, 0.35, r);
889:       float alpha = inner * (0.16 + veins * 0.48 + rim * 0.45);
890:       vec3 col = mix(cold, hot, clamp(rim + veins * 0.6, 0.0, 1.0));
891:       col += vec3(1.0, 0.32, 0.12) * pow(veins, 3.0) * 0.65;
892:       gl_FragColor = vec4(col, alpha);
893:     }
894:   `;
895: 
