941:         points.push(new THREE.Vector3(
942:           Math.cos(angle + t * 0.9) * radius * (1 - t * 0.34),
943:           0.04 + Math.sin(t * Math.PI) * rnd(0.2, 1.1),
944:           Math.sin(angle + t * 0.9) * radius * (1 - t * 0.34),
945:         ));
946:       }
947:       const curve = new THREE.CatmullRomCurve3(points);
948:       const tube = new THREE.Mesh(
949:         new THREE.TubeGeometry(curve, 12, 0.07 + rnd(0, 0.12), 4, false),
950:         new THREE.MeshStandardMaterial({ color: 0x2b090c, emissive: 0x7d1014, emissiveIntensity: 0.55, roughness: 0.5 }),
951:       );
952:       group.add(tube);
